[CmdletBinding()]
param([string]$OctaveCommand='octave-cli',[string]$LatexmkCommand='latexmk',[int]$PointsPerAxes=1000,[string]$OutputDirectory='')
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot -Parent;if(!$OutputDirectory){$OutputDirectory=Join-Path $repo 'benchmarks\output\m2.3-elements'}
$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory);$logs=Join-Path $OutputDirectory 'logs';$pdf=Join-Path $OutputDirectory 'pdf';$cache=Join-Path $OutputDirectory 'texmf';New-Item -ItemType Directory -Force $OutputDirectory,$logs,$pdf,$cache|Out-Null;$env:TEXMFVAR=$cache;$env:TEXMFCACHE=$cache
function Literal([string]$Value){$Value.Replace('\','/').Replace("'","''")};$bench=Literal $PSScriptRoot;$out=Literal $OutputDirectory
&$OctaveCommand --quiet --eval "addpath('$bench');benchmarkM23Elements('$out',$PointsPerAxes);";if($LASTEXITCODE-ne 0){throw 'M2.3 benchmark failed.'}
$rows=foreach($item in Import-Csv -Delimiter "`t" (Join-Path $OutputDirectory 'element-performance-raw.tsv')){$target=Join-Path $pdf $item.case;New-Item -ItemType Directory -Force $target|Out-Null;$timer=[Diagnostics.Stopwatch]::StartNew();$old=$ErrorActionPreference;$ErrorActionPreference='Continue';try{&$LatexmkCommand -lualatex -gg -interaction=nonstopmode -halt-on-error -file-line-error "-outdir=$target" $item.tex_path 2>&1|Set-Content -LiteralPath (Join-Path $logs "$($item.case).log") -Encoding utf8;$exit=$LASTEXITCODE}finally{$ErrorActionPreference=$old};$timer.Stop();if($exit-ne 0){throw "Compile failed: $($item.case)"};[pscustomobject]@{case=$item.case;axes=$item.axes;colorbars=$item.colorbars;points=$item.total_points;reader_s=$item.reader_s;renderer_s=$item.renderer_s;total_s=$item.total_s;tex_bytes=$item.tex_bytes;lualatex_s=[math]::Round($timer.Elapsed.TotalSeconds,6)}}
$rows|Export-Csv -Delimiter "`t" -NoTypeInformation -LiteralPath (Join-Path $OutputDirectory 'element-performance.tsv');$rows|Format-Table -AutoSize
